-- OrbitFS unified identity architecture: one user, optional customer and staff capabilities.
create table if not exists public.users (id uuid primary key default gen_random_uuid(),email text not null,username text,display_name text,first_name text,last_name text,status text not null default 'active' check(status in ('active','suspended','disabled','pending')),email_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists users_email_lower_uidx on public.users(lower(email));
create unique index if not exists users_username_lower_uidx on public.users(lower(username)) where username is not null;
create table if not exists public.staff_access (user_id uuid primary key references public.users(id) on delete cascade,enabled boolean not null default true,role text not null default 'staff',permissions jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists staff_access_enabled_idx on public.staff_access(enabled) where enabled=true;
alter table public.customers add column if not exists user_id uuid;
alter table public.user_profiles add column if not exists user_id uuid;
insert into public.users(id,email,username,display_name,first_name,last_name,status,email_verified_at,created_at,updated_at) select coalesce(c.auth_user_id,p.id,gen_random_uuid()),lower(coalesce(c.email,'unknown+'||coalesce(c.auth_user_id::text,p.id::text,gen_random_uuid()::text)||'@invalid.local')),c.username,coalesce(c.display_name,c.name,p.display_name),coalesce(c.first_name,p.first_name),coalesce(c.last_name,p.last_name),case when coalesce(c.status,p.status,'active') in ('active','suspended','disabled','pending') then coalesce(c.status,p.status,'active') else 'active' end,coalesce(c.email_verified_at,p.email_verified_at),coalesce(c.created_at,p.created_at,now()),now() from public.customers c full join public.user_profiles p on p.id=c.auth_user_id where not exists(select 1 from public.users u where u.id=coalesce(c.auth_user_id,p.id)) and c.email is not null;
insert into public.users(id,email,display_name,first_name,last_name,status,email_verified_at,created_at,updated_at) select p.id,lower(coalesce(a.email,'staff+'||p.id::text||'@invalid.local')),p.display_name,p.first_name,p.last_name,case when p.status in ('active','suspended','disabled','pending') then p.status else 'active' end,p.email_verified_at,coalesce(p.created_at,now()),now() from public.user_profiles p left join auth.users a on a.id=p.id where not exists(select 1 from public.users u where u.id=p.id);
update public.customers set user_id=auth_user_id where user_id is null and auth_user_id is not null;
update public.user_profiles set user_id=id where user_id is null;
alter table public.customers drop constraint if exists customers_user_id_fkey;
alter table public.user_profiles drop constraint if exists user_profiles_user_id_fkey;
alter table public.customers add constraint customers_user_id_fkey foreign key(user_id) references public.users(id) on delete cascade;
alter table public.user_profiles add constraint user_profiles_user_id_fkey foreign key(user_id) references public.users(id) on delete cascade;
create unique index if not exists customers_user_id_uidx on public.customers(user_id);
create unique index if not exists user_profiles_user_id_uidx on public.user_profiles(user_id);
insert into public.staff_access(user_id,enabled,role,permissions) select p.id,true,case when lower(coalesce(p.role,'')) in ('owner','system_admin','admin','superadmin','senior_support','staff') then lower(p.role) else 'staff' end,'{}'::jsonb from public.user_profiles p where lower(coalesce(p.role,'')) in ('owner','system_admin','admin','superadmin','senior_support','staff') on conflict(user_id) do update set enabled=true,role=excluded.role,updated_at=now();
insert into public.customers (user_id,auth_user_id,email,name,display_name,first_name,last_name,status,email_verified_at,metadata,updated_at) select u.id,null,u.email,u.display_name,u.display_name,u.first_name,u.last_name,'active',u.email_verified_at,jsonb_build_object('account_capabilities',jsonb_build_array('customer','staff'),'created_by_architecture_migration',true),now() from public.users u join public.staff_access s on s.user_id=u.id and s.enabled=true left join public.customers c on c.user_id=u.id where c.id is null on conflict do nothing;
alter table public.users enable row level security; alter table public.staff_access enable row level security; revoke all on public.users from anon,authenticated; revoke all on public.staff_access from anon,authenticated;
comment on table public.users is 'Canonical OrbitFS account identity. Customer and staff access attach to this identity.';
comment on table public.staff_access is 'Optional staff capability attached to a normal user account.';
comment on column public.customers.user_id is 'Canonical OrbitFS user identity. auth_user_id is legacy compatibility only.';
